// 出典など、URLだけを並べた <pre><code> をリンクの箇条書きにする（URL以外を含むコードはそのまま）
const URLLINE=/^https?:\/\/[^\s<>"'{}]+$/;
const srcList=urls=>`<ul class="src">${urls.map(u=>`<li><a class="src-url" href="${u}" rel="noopener" target="_blank">${u}</a></li>`).join('')}</ul>`;
const linkSources=h=>h.replace(/<pre><code>([\s\S]*?)<\/code><\/pre>/g,(m,inner)=>{const L=inner.split('\n').map(x=>x.trim()).filter(Boolean);return L.length&&L.every(x=>URLLINE.test(x))?srcList(L):m});
// 統合したページの旧URL用：本番では functions/_middleware.js の REDIRECTS で301。ミドルウェアが動かないときの予備として、canonical と自動転送だけのページを置く
const MOVED={};const moved=(from,to)=>{MOVED['/'+from]='/'+to;fs.mkdirSync(path.join(OUT,from),{recursive:true});fs.writeFileSync(path.join(OUT,from,'index.html'),`<!doctype html><html lang="ja"><head><meta charset="utf-8"><title>移動しました</title><link rel="canonical" href="${BASE}/${to}"><meta http-equiv="refresh" content="0; url=/${to}"></head><body><p>このページは<a href="/${to}">${BASE}/${to}</a>に移動しました。</p></body></html>`)};
// ツールページの追加の欄（data/tools.json の more）。値があるときだけ表示する。公式ページで確認できたことだけを書き、確認できない欄は空のままにする
// more: {checked:'YYYY-MM-DD', fit:[向いている人], notFit:[向かない人], diff:[[比べるツールのslug, 違い]], tried:{date, text}（実際に無料枠で試したこと）, sources:[確認した公式ページのURL]}
const toolMore=t=>{const m=t.more;if(!m)return '';let h='';
 if((m.fit||[]).length||(m.notFit||[]).length)h+=`<h2>${esc(t.name)}が向いている人・向かない人</h2>${(m.fit||[]).length?`<p><b>向いている人</b></p><ul>${m.fit.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${(m.notFit||[]).length?`<p><b>向かない人</b></p><ul>${m.notFit.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}`;
 if((m.diff||[]).length)h+=`<h2>似たツールとの違い</h2><ul>${m.diff.map(([sl,x])=>{const o=tools.find(y=>y.slug===sl);return `<li>${o?`<a href="../${o.slug}/">${esc(o.name)}</a>との違い：`:''}${esc(x)}</li>`}).join('')}</ul>`;
 if(m.tried&&m.tried.text)h+=`<h2>無料枠で実際に試したこと</h2><p>${esc(m.tried.text)}</p><p class="muted">試した日：${esc(m.tried.date||'')}</p>`;
 if(h)h+=`<p class="muted">この欄は${m.checked?esc(m.checked)+'に':''}公式ページ${(m.sources||[]).length?`（${m.sources.map(u=>`<a class="src-url" href="${esc(u)}" rel="noopener" target="_blank">${esc(u)}</a>`).join('、')}）`:''}で確認した内容です。</p>`;
 return h};
// 記事の冒頭近くに出す「この記事の調べ方」。出典の箇条書き（URLの数とドメイン）と、記事のデータ（updated・method）から作る。事実でないことは書かない（人が確認した範囲は method.human があるときだけ書く）
const howBox=(a,h)=>{const urls=[...h.matchAll(/<a class="src-url" href="([^"]+)"/g)].map(m=>m[1]);const hosts=[...new Set(urls.map(u=>{try{return new URL(u.replace(/&amp;/g,'&')).hostname.replace(/^www\./,'')}catch(e){return ''}}).filter(Boolean))];const md=a.method||{};
 return `<div class="howto"><b>この記事の調べ方</b><p>${urls.length?`最終確認日（${esc(a.updated||a.date||'')}）までに、記事の「出典」に挙げたページ${urls.length}件（${hosts.slice(0,4).map(esc).join('・')}${hosts.length>4?'など':''}）を読んで書いています。`:`料金や機能は、記事中にリンクした公式ページをもとに書いています。`}文章の作成にはAIを使っています（<a href="../../about/">このサイトについて</a>）。${md.human?`人が確認したこと：${esc(md.human)}`:''}</p></div>`};
// 用語の定義：記事に出てくる用語に、冒頭近くで1文の定義を付ける。意味が違う使い方をしている記事は skip に入れる
const GLOSSARY=[
 ['トークン',/トークン/,'AIが文章を処理するときに数える単位（文字や単語のまとまり）。料金や利用上限の数え方に使われます。',['claude-models-google-cloud']],
 ['クレジット',/クレジット(?!カード)/,'ツールの中で機能を使うたびに消費する利用枠の単位。1回あたりの消費量や補充のされ方はツールごとに違います。',[]],
 ['API',/API/,'プログラムからサービスの機能を呼び出すための窓口。画面から使うのではなく、自分のアプリやシステムに組み込むときに使います。',[]],
 ['従量課金',/従量課金/,'月額の固定料金ではなく、使った量（分数・回数など）に応じて料金がかかる仕組み。',[]],
 ['商用利用',/商用利用/,'作ったものを仕事や収益化（販売・広告収入など）に使うこと。できるかどうかはプランと利用規約で決まります。',[]],
 ['MCP',/MCP/,'Model Context Protocol の略。AIアプリと外部のツールやデータをつなぐための共通の仕組みです。',[]]];
const termBox=a=>{const txt=a.body.replace(/<[^>]+>/g,'');const hit=GLOSSARY.filter(([n,re,d,skip])=>!skip.includes(a.slug)&&re.test(txt));return hit.length?`<div class="terms"><b>この記事に出てくる用語</b><dl>${hit.map(([n,re,d])=>`<dt>${esc(n)}</dt><dd>${esc(d)}</dd>`).join('')}</dl></div>`:''};
const LD=o=>`<script type="application/ld+json">${JSON.stringify(o).replace(/</g,'\\u003c')}</script>`;
// Bing Webmaster Tools の確認タグ（msvalidate.01）。登録後に値を入れる。空なら出力しない
const MSVALIDATE='';
const X_URL='https://x.com/888marui';
const ORG={'@type':'Organization','@id':BASE+'/#organization',name:SITE,url:BASE+'/',logo:BASE+'/icon-512.png',sameAs:[X_URL],founder:{'@id':BASE+'/about/#person'}};
const PERSON={'@type':'Person','@id':BASE+'/about/#person',name:'マルイ',url:BASE+'/about/',sameAs:[X_URL],description:'AIツール新着便の運営者。新しく出たAIツールの料金・機能・日本語対応を公式サイトで確認し、日本語で紹介しています。'};
// 公式サイトで確認済みの最低価格（tools.json の pricing に金額が明記されているものだけ）。未確認のツールは入れない
