const swExtra=t=>({...(NO_OS.has(t.slug)?{}:{operatingSystem:'Web'}),...(OFFERS[t.slug]?{offers:{'@type':'Offer',price:String(OFFERS[t.slug][0]),priceCurrency:OFFERS[t.slug][1],url:t.url}}:{})});
const crumbs=items=>({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['ホーム',BASE+'/'],...items].map(([n,u],i)=>({'@type':'ListItem',position:i+1,name:n,item:u}))});
const cut=(s,n=120)=>{s=String(s).replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n-1)+'…':s};
const SEOFIX=require('./data/seo_fix.json');
const last=tools.map(t=>t.checked&&t.checked>t.added?t.checked:t.added).sort().pop();
const STO={"ai-gijiroku-tool-hikaku": "AI議事録ツール7つの無料枠を比較｜無料でどこまで使えるか", "muryou-ai-tool-ichiran": "無料で使える生成AI・AIツール一覧｜公式で無料プランを確かめた25件", "muryou-mojiokoshi-ai": "文字起こしAIを無料で使う｜Notta月120分・Otter月300分の上限", "ai-slide-sakusei-hikaku": "AIスライド作成ツール比較｜イルシル・Gamma・Felo", "ai-writing-tool-hikaku": "AIライティングツール比較｜Value AI Writerなど5つ", "ai-yomiage-elevenlabs-voicevox": "AI音声読み上げ｜ElevenLabsとVOICEVOXの料金・商用", "chatgpt-igai-ai-hikaku": "ChatGPT以外の生成AI比較｜Gemini・Copilot", "douga-seisei-ai-hikaku": "動画生成AI比較｜Runway・Luma・HeyGenの料金と無料枠", "gazou-seisei-ai-muryou": "無料で使える画像生成AI｜Gemini・Krea・Napkin AI", "mojiokoshi-ai-hikaku": "文字起こしAI比較｜Notta・Rimo・Otter・tl;dvの料金", "notebooklm-muryou-jougen": "NotebookLM無料版の上限まとめ｜ソース数・回数", "rakurin-hyouban-ryoukin": "ラクリンの評判・料金｜無料で毎月約2記事・有料は4,980円/月〜", "plaud-tsukaikata-ryoukin": "Plaudの使い方・料金｜本体¥27,500〜・無料プランは毎月300分", "fliki-tsukaikata-shouyou": "Flikiの使い方と料金｜無料は月3クレジット・商用は年払い$21/月〜", "tools/gemini-agent-workspace": "Gemini agentとは？使い方・料金", "tools/notebooklm": "NotebookLM（Gemini Notebook）とは？使い方"};function ST(x,k){if(STO[k])x=STO[k];x=x.replace('（2026年10月版）','');return (x+'｜'+SITE).length<=35?x+'｜'+SITE:x}
// 検索結果に出るタイトル・説明文（2026-11-02。記録は docs/ctr-changes.md）：開く前に「何が分かるか」が見えるよう、データにある事実だけで組み立てる。
// 長さの目安はタイトル30〜35字前後・説明文70〜110字前後。サイト名は入るときだけ付ける（ST と同じ）。「未確認」の値はタイトルに出さない
const TMAX=36,DMAX=110;
const okv=v=>v!=null&&String(v).trim()!==''&&!/未確認|undefined/.test(String(v));
const fit=(...c)=>c.find(x=>x&&x.length<=TMAX);
const withSite=x=>(x+'｜'+SITE).length<=35?x+'｜'+SITE:x;
// 説明文は文の切れ目で切る（70字以上残るとき）。切れ目がなければ cut と同じく「…」
const cutS=(s,n=DMAX)=>{s=String(s).replace(/\s+/g,' ').trim();if(s.length<=n)return s;const i=s.lastIndexOf('。',n-1);return i>=69?s.slice(0,i+1):cut(s,n)};
const shortName=t=>t.name.replace(/（[^）]*）/g,'').trim();
// 値札の中身（料金欄の無料プランの区切り）のかっこ内から、数字を含む短い項目を1つだけ取り出す（例：週500AIクレジット）。言い換えはしない
const freeLimit=t=>{const m=tagText(t).match(/（([^）]*)）/);return m?m[1].split(/[、・]/).map(x=>x.trim()).find(x=>/\d/.test(x)&&x.length<=16&&!/[（）「」]|は/.test(x)&&!/^[￥¥$€]?\s?[\d,.]+円?$/.test(x))||'':''};
// 最安の有料プランの金額だけ（例：1,185円/月〜）。月・年の単位が付いた金額で、注記（※・別途・従量・限定など）がないときだけ。「〜」は最安からの意味
const priceShort=t=>{const s=String(t.cheapest||'');if(!okv(s)||/※|別途|従量|トークン|API|限定|未確認/.test(s))return '';const m=s.match(/([￥¥$€]\s?[\d,.]+|[\d,]+円)\s*\/\s*(月|年)/);return m?m[1].replace(/\s/g,'')+'/'+m[2]+'〜':''};
