const jd=d=>{const [y,m,dd]=d.split('-');return `${+y}年${+m}月${+dd}日`};
const NEWSBOX=rel=>NEWS.length?`<section><h2>海外AIニュース</h2>${NEWS.slice(0,3).map(n=>`<div class="card"><div class="date">${jd(n.date)}・${esc(n.source)}</div><h3><a href="${newsHref(n,rel)}">${esc(n.title)}</a></h3><p>${esc(n.summary[0])}</p></div>`).join('')}<p><a href="${rel}news/">海外AIニュースをもっと見る</a></p></section>`:'';
const artTools=a=>a.tools||tools.filter(t=>a.body.includes(t.name)).map(t=>t.slug);
const toolArts=t=>artsL.filter(a=>artTools(a).includes(t.slug));
// 話題ごとのまとめ（ハブ）記事と、その話題の個別記事（data/hubs.json。docs/internal-links.md のハブに合わせる。2026-11-02、2026-11-03 に check.js でも使うため data/ へ移した）。記事の末尾の「この話題のまとめ記事」「次に読む記事」に使う
const HUBS=require('./data/hubs.json');
const hubsOf=a=>Object.entries(HUBS).filter(([h,[,m]])=>m.includes(a.slug)).map(([h,[topic]])=>[artsL.find(b=>b.slug===h),topic]).filter(([b])=>b);
const toolNames=sl=>sl.map(z=>(tools.find(t=>t.slug===z)||{}).name).filter(Boolean).map(n=>n.replace(/（[^）]*）/g,''));
const readNext=a=>{let h='';const hubs=hubsOf(a);
 if(hubs.length)h+=`<h2>この話題のまとめ記事</h2><ul class="nextlist">${hubs.map(([b,topic])=>`<li><a href="../${b.slug}/">${esc(b.title)}</a><span class="why">「${esc(topic)}」の記事をまとめて比べています</span></li>`).join('')}</ul>`;
 const mine=artTools(a),own=HUBS[a.slug]?HUBS[a.slug][1]:[],sib=new Set([...own,...hubs.flatMap(([b])=>HUBS[b.slug][1])]);
 const cand=artsL.filter(b=>b.slug!==a.slug&&!hubs.some(([x])=>x.slug===b.slug)).map(b=>{const sh=artTools(b).filter(z=>mine.includes(z));return [b,sh,sib.has(b.slug)]});
 const score=([b,sh,s])=>sh.length*2+(s?1:0);
 const pick=cand.filter(c=>score(c)>0).sort((x,y)=>score(y)-score(x)||(y[0].updated||y[0].date||'').localeCompare(x[0].updated||x[0].date||'')).slice(0,3);
 if(pick.length<3)pick.push(...cand.filter(c=>!pick.includes(c)).sort((x,y)=>(y[0].updated||y[0].date||'').localeCompare(x[0].updated||x[0].date||'')).slice(0,3-pick.length).map(([b])=>[b,[],false,'new']));
 h+=`<h2>次に読む記事</h2><ul class="nextlist">${pick.map(([b,sh,s,nw])=>`<li><a href="../${b.slug}/">${esc(b.title)}</a><span class="why">${nw?'最近更新した記事':sh.length?esc(toolNames(sh).slice(0,3).join('・'))+'も扱っています':'同じ話題の記事'}</span></li>`).join('')}</ul>`;
 return h};
// ツールページの末尾の「次に見るページ」（2026-11-02）：このツールを比べている記事（比較記事を先に、最大4件）と、似たツール（本文で違いを書いたツール→同じカテゴリ→同じ記事で扱うツール、最大4件）。理由を1行で添える
