page('about/index.html',`このサイトについて｜${SITE}`,`${SITE}の運営方針`,`<article class="prose"><h1>このサイトについて</h1><p>${SITE}は、新しく出た・更新されたAIツールを日本語で紹介する新着まとめサイトです。</p><h2>編集方針</h2><ul><li>情報は各ツールの公式サイトで確認し、確認できない項目は「未確認」と表記します。</li><li>誇張した表現や「稼げる」といった収益の約束はしません。</li><li>暗号資産の取引所や、投資の助言をするツールは掲載しません。</li><li>紹介文の作成にはAIを使っています。</li></ul><h2>広告について</h2><p>当サイトはアフィリエイトプログラムを利用しています。「PR」と表示したリンクから登録・購入があった場合、運営者が報酬を受け取ることがあります。掲載内容や評価は報酬の有無で変えません。</p><h2>運営者情報</h2><table><tr><th>サイト名</th><td>${SITE}</td></tr><tr><th>運営者</th><td>マルイ</td></tr><tr><th>X</th><td><a href="https://x.com/888marui" rel="noopener">https://x.com/888marui</a></td></tr><tr><th>連絡先</th><td><a href="../contact/">お問い合わせページ</a></td></tr></table><p><a href="../privacy/">プライバシーポリシー</a></p></article>`,'../');
page('newsletter/index.html',`メール配信｜${SITE}`,'新着AIツールのメール配信','<article class="prose"><h1>メール配信（準備中）</h1><div class="box">新着AIツールをお届けするメール配信は<b>準備中</b>です。配信の頻度は、始めるときにこのページでお知らせします。</div></article>','../');
const AIO=require('./data/aio.js');
const artBody=a=>{const x=AIO[a.slug]||{};let h=linkSources(a.body);for(const [o,n] of Object.entries(x.h2||{}))h=h.split(`<h2>${o}</h2>`).join(`<h2>${n}</h2>`);h=h.replace(/(<\/h1><p class="muted">更新日：)\d+年\d+月\d+日/,(m,p)=>p+jd(a.updated||a.date||'2026-10-16'));h=h.replace('</h1>',`</h1><p class="byline">運営者：<a href="../../about/">マルイ</a>／最終確認日 ${a.updated||a.date||'2026-10-16'}</p>${howBox(a,h)}${termBox(a)}`);if(x.lead)h=h.replace('</h1>',`</h1><div class="box"><b>結論：</b>${esc(x.lead)}</div>`);else{const i=h.indexOf('<p><b>結論：</b>');if(i>=0&&i<2500){const j=h.indexOf('</p>',i);h=h.slice(0,i)+'<div class="box">'+h.slice(i+3,j)+'</div>'+h.slice(j+4)}}{const af=artTools(a).map(z=>tools.find(t=>t.slug===z)).filter(t=>t&&t.affiliate);if(af.length){const box=`<div class="ctabox"><p>この記事で紹介している公式サイト<span class="pr">PR</span></p>${af.map(t=>`<a class="cta" href="${esc(t.affiliate.url)}" rel="sponsored nofollow noopener" target="_blank">${esc(t.name)}の公式サイト</a>`).join('')}<p class="muted" style="font-weight:400;margin:6px 0 0">ボタンはアフィリエイトリンク（PR）です。料金は申し込み前に公式サイトでご確認ください。</p></div>`;const b=h.indexOf('</div>',h.indexOf('<b>結論：</b>'));const at=h.includes('<b>結論：</b>')?b+6:h.indexOf('</h1>')+5;h=h.slice(0,at)+box+h.slice(at);const t1=h.indexOf('</table>');if(t1>0)h=h.slice(0,t1+8)+box+h.slice(t1+8);}}if(x.recommend){const rec=`<h2>こんな人におすすめ</h2><ul>${x.recommend.map(([n,w])=>`<li><b>${esc(n)}</b>：向いている人は${esc(w)}</li>`).join('')}</ul>`;const t=h.indexOf('</table>'),k=t<0?-1:h.indexOf('<h2>',t);h=k<0?h+rec:h.slice(0,k)+rec+h.slice(k);}if(/rel="sponsored/.test(h)){h=h.replace(/<p class="muted">PR：[^<]*<\/p>/g,'');h=h.replace('</h1>','</h1><p class="prnote"><span class="pr">PR</span> この記事にはアフィリエイトリンク（広告）が含まれます。「PR」と表示したリンクはアフィリエイト（広告）です。掲載内容は報酬で変えていません。</p>');}if(x.faq)h+=`<h2>よくある質問</h2>${x.faq.map(([q,an])=>`<h3>Q. ${esc(q)}</h3><p>A. ${esc(an)}</p>`).join('')}`;return h;};
const faqLD=a=>{const x=AIO[a.slug];return x&&x.faq?[{'@context':'https://schema.org','@type':'FAQPage',mainEntity:x.faq.map(([q,an])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:an}}))}]:[];};
// title・description の「Nつ」が見出し（h1）と食い違っていたら警告する（記事の更新でツール数が変わったときの直し忘れ防止）
for(const a of arts){const h1=(a.body.match(/<h1>([\s\S]*?)<\/h1>/)||[])[1]||'';const n=v=>(String(v).match(/(\d+)つ/)||[])[1];const k='articles/'+a.slug+'/';for(const [w,v] of [['title',artTitle(a)],['description',SEOFIX.meta[k]||a.desc]])if(n(h1)&&n(v)&&n(h1)!==n(v))console.warn(`[要確認] ${k} の${w}は「${n(v)}つ」、見出しは「${n(h1)}つ」です`)}
for(const a of arts)page(`articles/${a.slug}/index.html`,artTitle(a),(AIO[a.slug]&&AIO[a.slug].lead&&!a.desc.includes(AIO[a.slug].lead.split('。')[0])?AIO[a.slug].lead.split('。')[0]+'。'+a.desc:a.desc),'<article class="prose">'+artBody(a)+(()=>{const at=artTools(a).map(x=>tools.find(t=>t.slug===x)).filter(Boolean);return readNext(a)+(at.length?`<h2>この記事で紹介したツールの詳細</h2><ul>${at.map(t=>`<li><a href="../../tools/${t.slug}/">${esc(t.name)}</a>（料金・日本語対応・公式サイト）</li>`).join('')}</ul>`:'')})()+`<div class="nextbox"><h2>次にやること</h2><p class="muted" style="margin:0">関連記事を読むか、カテゴリから似たツールを探してください。</p><div class="nextacts"><a class="cta sec" href="../../categories/">カテゴリから探す</a><a class="cta sec" href="../../articles/muryou-ai-tool-ichiran/">無料で使えるツール</a><a class="cta sec" href="../../articles/">記事一覧</a></div></div><p class="muted">新着ツールの<a href="../../newsletter/">メール配信</a>も準備しています。公開日 ${a.date||'2026-10-16'}／更新日 ${a.updated||a.date||'2026-10-16'}</p></article>`,'../../',[{'@context':'https://schema.org','@type':'Article',headline:artH1(a),description:a.desc,datePublished:a.date||'2026-10-16',dateModified:a.updated||a.date||'2026-10-16',inLanguage:'ja',author:PERSON,publisher:ORG,mainEntityOfPage:`${BASE}/articles/${a.slug}/`,image:fs.existsSync(`static/og/${a.slug}.png`)?`${BASE}/og/${a.slug}.png`:BASE+'/ogp.png'},crumbs([['記事',BASE+'/articles/'],[artH1(a),`${BASE}/articles/${a.slug}/`]]),...faqLD(a)],a.noindex?'<meta name="robots" content="noindex,follow">':'');
page('articles/index.html',`記事一覧｜${SITE}`,`AIツールの比較・使い方記事${artsL.length}本の一覧。文字起こし・画像生成・動画生成・AIチャット・音声読み上げなどを、公式サイトで確認した料金や無料枠で整理しています。`,`<h1>記事一覧</h1>${artsL.map(a=>`<div class="card"><h2><a href="./${a.slug}/">${esc(a.title)}</a></h2><p>${esc(a.desc)}</p></div>`).join('')}`,'../',[{'@context':'https://schema.org','@type':'ItemList',name:'記事一覧',numberOfItems:artsL.length,itemListElement:artsL.map((a,i)=>({'@type':'ListItem',position:i+1,url:`${BASE}/articles/${a.slug}/`,name:a.title}))},crumbs([['記事',BASE+'/articles/']])]);

