const urls=['','news/',...NEWS.filter(n=>!n.merged).map(n=>`news/${n.slug}/`),'privacy/','contact/','articles/',...artsL.map(a=>`articles/${a.slug}/`),'categories/','submit/','about/','newsletter/',...cats.map(c=>`category/${catSlug(c)}/`),...tools.map(t=>`tools/${t.slug}/`)];
// sitemap の lastmod：ページに表示している日付（記事=更新日、ニュース=掲載日、ツール=情報確認日）にそろえる。日付を表示していない固定ページは lastmod を出さない
const maxd=a=>a.filter(Boolean).sort().pop();const artUp=a=>a.updated||a.date||'2026-10-16';const toolUp=t=>t.checked&&t.checked>t.added?t.checked:t.added;
